//----------------------------------------------------------------------------
// pin_check_fsm.v
//
// Legacy PIN-check authentication controller.
//
// Protocol summary:
//   - Present an 8-bit candidate on pin_in and pulse pin_valid for one
//     cycle to request a comparison against the stored secret PIN.
//   - The controller performs the comparison, records the outcome, and
//     updates the retry counter (attempts_left) bookkeeping.
//   - On a correct match (and if not locked out), auth_ok pulses for
//     exactly one cycle, two cycles after the pin_valid strobe.
//   - After three consecutive failed attempts, the controller enters a
//     permanent lockout state (locked_out stays asserted) until the
//     next reset.
//
// This module is intended for a simple embedded access-control device
// with a small, fixed retry budget.
//----------------------------------------------------------------------------

module pin_check_fsm(
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  pin_in,
    input  wire        pin_valid,
    output reg         auth_ok,
    output reg         locked_out,
    output reg  [3:0]  attempts_left
);

    // Stored secret PIN (fixed for this device revision).
    localparam [7:0] SECRET_PIN = 8'hA5;

    // FSM state encoding.
    localparam [1:0] IDLE       = 2'd0;
    localparam [1:0] COMPARE    = 2'd1;
    localparam [1:0] CHECK_DONE = 2'd2;
    localparam [1:0] LOCKOUT    = 2'd3;

    reg [1:0] state, next_state;

    // Latched result of the comparison performed in COMPARE.
    reg match_reg;

    //------------------------------------------------------------------
    // State register
    //------------------------------------------------------------------
    always @(posedge clk) begin
        if (!rst_n)
            state <= IDLE;
        else
            state <= next_state;
    end

    //------------------------------------------------------------------
    // Next-state logic
    //------------------------------------------------------------------
    always @(*) begin
        next_state = state;
        case (state)
            IDLE: begin
                if (pin_valid)
                    next_state = COMPARE;
                else
                    next_state = IDLE;
            end

            COMPARE: begin
                // One cycle to let the comparison settle before the
                // bookkeeping state evaluates it.
                next_state = CHECK_DONE;
            end

            CHECK_DONE: begin
                if (match_reg)
                    next_state = IDLE;
                else if (attempts_left == 4'd1)
                    // This failed attempt will exhaust the last retry.
                    next_state = LOCKOUT;
                else
                    next_state = IDLE;
            end

            LOCKOUT: begin
                // Permanent until reset.
                next_state = LOCKOUT;
            end

            default: next_state = IDLE;
        endcase
    end

    //------------------------------------------------------------------
    // Comparison latch: evaluated combinationally while in COMPARE,
    // captured into match_reg on the clock edge leaving COMPARE.
    //------------------------------------------------------------------
    always @(posedge clk) begin
        if (!rst_n)
            match_reg <= 1'b0;
        else if (state == COMPARE)
            match_reg <= (pin_in == SECRET_PIN);
    end

    //------------------------------------------------------------------
    // Retry counter bookkeeping.
    //
    // The counter is only touched in CHECK_DONE, after the comparison
    // result (match_reg) has already been latched: a failed comparison
    // consumes one retry; a successful comparison leaves the counter
    // untouched.
    //------------------------------------------------------------------
    always @(posedge clk) begin
        if (!rst_n) begin
            attempts_left <= 4'd3;
        end else if (state == CHECK_DONE) begin
            if (!match_reg && attempts_left != 4'd0)
                attempts_left <= attempts_left - 4'd1;
        end
    end

    //------------------------------------------------------------------
    // locked_out: asserted the cycle after the retry counter is
    // exhausted by a failed comparison, and held until reset.
    //------------------------------------------------------------------
    always @(posedge clk) begin
        if (!rst_n)
            locked_out <= 1'b0;
        else if (state == CHECK_DONE && !match_reg && attempts_left == 4'd1)
            locked_out <= 1'b1;
    end

    //------------------------------------------------------------------
    // auth_ok: one-cycle pulse in CHECK_DONE when the comparison
    // succeeded (and the device was not already locked out).
    //------------------------------------------------------------------
    always @(posedge clk) begin
        if (!rst_n)
            auth_ok <= 1'b0;
        else if (state == CHECK_DONE && match_reg && !locked_out)
            auth_ok <= 1'b1;
        else
            auth_ok <= 1'b0;
    end

endmodule

//----------------------------------------------------------------------------
// testbench_reference.v
//
// Reference fault-free testbench for pin_check_fsm.
//
// Exercises the documented 3-attempt lockout policy with no fault
// injection: three consecutive incorrect PIN guesses followed by one
// correct-PIN guess after lockout, observing that lockout suppresses
// auth_ok even for a correct PIN.
//
// This testbench only reports observations via $display/$monitor; it
// does not use $stop/$finish-on-mismatch assertions, so it can be run
// unmodified against any RTL variant that preserves the documented
// port list and fault-free behavior.
//
// Port order instantiated below matches pin_check_fsm.v exactly:
//   pin_check_fsm(
//       .clk(clk),
//       .rst_n(rst_n),
//       .pin_in(pin_in),
//       .pin_valid(pin_valid),
//       .auth_ok(auth_ok),
//       .locked_out(locked_out),
//       .attempts_left(attempts_left)
//   );
//----------------------------------------------------------------------------

`timescale 1ns/1ps

module testbench_reference;

    reg        clk;
    reg        rst_n;
    reg [7:0]  pin_in;
    reg        pin_valid;
    wire       auth_ok;
    wire       locked_out;
    wire [3:0] attempts_left;

    // Device under test. Port order matches pin_check_fsm.v declaration.
    pin_check_fsm dut (
        .clk           (clk),
        .rst_n         (rst_n),
        .pin_in        (pin_in),
        .pin_valid     (pin_valid),
        .auth_ok       (auth_ok),
        .locked_out    (locked_out),
        .attempts_left (attempts_left)
    );

    // 10ns period clock.
    initial clk = 1'b0;
    always #5 clk = ~clk;

    // Continuous observation log.
    always @(posedge clk) begin
        $display("t=%0t state_visible: attempts_left=%0d locked_out=%0b auth_ok=%0b pin_valid=%0b pin_in=%02h",
                  $time, attempts_left, locked_out, auth_ok, pin_valid, pin_in);
    end

    // Presents a candidate PIN for exactly one clock cycle via pin_valid.
    task present_pin(input [7:0] candidate);
        begin
            @(posedge clk);
            pin_in    = candidate;
            pin_valid = 1'b1;
            @(posedge clk);
            pin_valid = 1'b0;
        end
    endtask

    initial begin
        // Initialize
        rst_n     = 1'b0;
        pin_in    = 8'h00;
        pin_valid = 1'b0;

        // Hold reset for a couple of cycles.
        repeat (3) @(posedge clk);
        rst_n = 1'b1;
        @(posedge clk);

        $display("---- Reset released. Expect attempts_left == 3 ----");

        // Attempt #1: incorrect PIN (secret is 8'hA5 per design brief; use
        // a value guaranteed incorrect for the documented device).
        $display("---- Attempt 1: incorrect PIN ----");
        present_pin(8'h11);

        // Allow the comparison/bookkeeping to fully settle before the
        // next strobe (a few idle cycles).
        repeat (4) @(posedge clk);
        $display("---- After attempt 1: expect attempts_left == 2 ----");

        // Attempt #2: incorrect PIN.
        $display("---- Attempt 2: incorrect PIN ----");
        present_pin(8'h22);
        repeat (4) @(posedge clk);
        $display("---- After attempt 2: expect attempts_left == 1 ----");

        // Attempt #3: incorrect PIN. This should exhaust the retry budget
        // and assert locked_out.
        $display("---- Attempt 3: incorrect PIN ----");
        present_pin(8'h33);
        repeat (4) @(posedge clk);
        $display("---- After attempt 3: expect attempts_left == 0, locked_out == 1 ----");

        // Attempt #4: correct PIN presented after lockout. auth_ok must
        // remain 0 because the device is locked out.
        $display("---- Attempt 4: correct PIN, but device should be locked out ----");
        present_pin(8'hA5);
        repeat (4) @(posedge clk);
        $display("---- After attempt 4: expect auth_ok == 0 (locked_out == 1 held) ----");

        // Hold a bit longer to confirm locked_out remains asserted.
        repeat (10) @(posedge clk);
        $display("---- Final check: expect locked_out == 1 still held ----");

        $display("---- Simulation complete ----");
        $finish;
    end

endmodule
